    public float LanbaiOverlayHandoverAt(float t0, float t1)
    {
        if (!_built) _Build();
        float best = -1f;
        float[] w = overlayWindowsFlat;
        if (w == null || t1 <= t0) return best;
        for (int i = 0; i + 1 < w.Length; i += 2)
        {
            if (!(w[i] < t1 && w[i + 1] > t0)) continue;
            float h = Mathf.Max(t0, w[i]);
            if (best < 0f || h < best) best = h;
